160	        loop {
161	            if !visited.insert(ancestor) {
162	                return Err(ProcessFamilyAncestryError::Cycle { ancestor });
163	            }
164	            if self.terminal.contains_key(&ancestor) {
165	                return Ok(true);
166	            }
167	            let mut parents = self
168	                .direct_children
169	                .iter()
170	                .filter(|(_, children)| children.contains_key(&ancestor))
171	                .map(|(parent, _)| *parent);
172	            let Some(parent) = parents.next() else {
173	                return Ok(false);
174	            };
175	            if let Some(second_parent) = parents.next() {
176	                return Err(ProcessFamilyAncestryError::MultipleParents {
177	                    child: ancestor,
178	                    first_parent: parent,
179	                    second_parent,
180	                });
181	            }
182	            ancestor = parent;
183	        }
184	    }
185	}
