188	pub(super) struct ProcessSignalRegistry {
189	    processes: Mutex<BTreeMap<(i32, u64), Weak<ProcessBinding>>>,
190	    // Logical process ancestry is independent of host join-handle placement.
191	    // It is retained by exact generation until a wait consumes a zombie or an
192	    // exit-time auto-reap decision removes it. This is the fail-closed boundary
193	    // for reparenting, which this change does not claim to implement.
194	    family: Mutex<ProcessFamilyState>,
195	    // Run-scoped at-most-once admission. Standard-signal coalescing is not an
196	    // operation ledger: after dequeue, the same child could otherwise enqueue
197	    // a second SIGCHLD. Retain exact generations until the run ends.
198	    child_publications: Mutex<BTreeMap<(i32, u64), ChildPublicationRecord>>,
199	    // No callbacks or G references. An eventual owner must make its own run
200	    // terminal after saving FailedAfterCommit. This latch refuses further
201	    // publication; it is not a substitute for that owner transition.
202	    failure: Mutex<Option<PublicationFailure>>,
203	    controlled: AtomicBool,
204	    permits: Mutex<BTreeMap<(i32, u64, i32, u64), RegisteredPermit>>,
205	    completed_permits: Mutex<BTreeMap<(i32, u64, i32, u64), reverie::SignalDeliveryPermit>>,
206	    run_failure: Mutex<Weak<crate::failure::RunFailure>>,
207	    reported_failure: Mutex<Option<crate::Error>>,
208	    failure_forwarded: AtomicBool,
209	}
