211	impl ProcessSignalRegistry {
212	    pub(super) fn register(
213	        &self,
214	        state: &LoadedStaticElf,
215	        files: &Arc<Mutex<FileTableState>>,
216	        generation: u64,
217	        parent: Option<SignalProcessId>,
218	    ) -> Result<Arc<ProcessBinding>, SignalProcessId> {
219	        let identity = SignalProcessId {
220	            tgid: reverie::Pid::from_raw(state.pid),
221	            generation,
222	        };
223	        // Successful exec and same-process executor reconstruction retain the
224	        // process generation; they are not a fork edge and cannot make a
225	        // process its own child.
226	        let parent = parent.filter(|candidate| *candidate != identity);
227	        let binding = Arc::new(ProcessBinding {
228	            identity,
229	            parent,
230	            transaction: Arc::downgrade(&state.signal_transaction),
231	            lifecycle: Arc::downgrade(&state.task_lifecycle),
232	            image: Mutex::new(CurrentImage {
233	                revision: ImageRevision(Arc::new(())),
234	                files: Arc::downgrade(files),
235	                signals: Arc::downgrade(&state.process_signals),
236	            }),
237	        });
238	        if let Some(parent) = parent {
239	            let mut family = self.family.lock().unwrap_or_else(|p| p.into_inner());
240	            let parent_key = process_key(parent);
241	            if family.terminal.contains_key(&parent_key) {
242	                return Err(parent);
243	            }
244	            let previous = family
245	                .direct_children
246	                .entry(parent_key)
247	                .or_default()
248	                .insert(process_key(binding.identity), DirectChildState::Live);
249	            debug_assert!(previous.is_none(), "duplicate KVM child process generation");
250	        }
251	        let mut processes = self.processes.lock().unwrap_or_else(|p| p.into_inner());
252	        processes.retain(|_, process| process.strong_count() != 0);
253	        processes.insert((state.pid, generation), Arc::downgrade(&binding));
254	        Ok(binding)
255	    }
256	
257	    fn lookup(&self, identity: SignalProcessId) -> Option<Arc<ProcessBinding>> {
258	        self.processes
259	            .lock()
260	            .unwrap_or_else(|p| p.into_inner())
261	            .get(&(identity.tgid.as_raw(), identity.generation))?
262	            .upgrade()
263	    }
264	
265	    /// Freeze the exact process generation at its first exact task failure.
266	    /// Descendants may still finish successfully while the runtime unwinds,
267	    /// but their completion is teardown rather than a new logical child-exit
268	    /// publication to the failed parent.
269	    pub(super) fn record_process_failure(&self, process: SignalProcessId) {
270	        let parent = self.lookup(process).and_then(|binding| binding.parent);
271	        let mut family = self.family.lock().unwrap_or_else(|p| p.into_inner());
272	        let process_family_key = process_key(process);
273	        let replace_success = matches!(
274	            family.terminal.get(&process_family_key),
275	            None | Some(
276	                ProcessFamilyExit::Root
277	                    | ProcessFamilyExit::Child(_)
278	                    | ProcessFamilyExit::RunTeardownChild { .. }
279	            )
280	        );
281	        if !replace_success {
282	            // Preserve the first typed fatal family invariant instead of
283	            // replacing its actionable cause with a generic peer failure.
284	            return;
285	        }
286	        family
287	            .terminal
288	            .insert(process_family_key, ProcessFamilyExit::Failed);
289	        if let Some(parent) = parent {
290	            let parent_key = process_key(parent);
291	            if let Some(children) = family.direct_children.get_mut(&parent_key) {
292	                children.remove(&process_family_key);
293	                if children.is_empty() {
294	                    family.direct_children.remove(&parent_key);
295	                }
296	            }
297	        }
298	    }
299	
300	    /// Freeze one process's terminal parent/wait policy at the authoritative
301	    /// lifecycle transition. Host join completion and the later Tool callback
302	    /// only consume this snapshot; they cannot resample a parent's newer
303	    /// SIGCHLD disposition.
304	    pub(super) fn record_process_exit(
305	        &self,
306	        process: SignalProcessId,
307	        status: reverie::ExitStatus,
308	    ) -> ProcessFamilyExit {
309	        if let Some(exit) = self
310	            .family
311	            .lock()
312	            .unwrap_or_else(|p| p.into_inner())
313	            .terminal
314	            .get(&process_key(process))
315	            .copied()
316	        {
317	            return exit;
318	        }
319	
320	        let binding = self.lookup(process);
321	        let parent_identity = binding.as_ref().and_then(|binding| binding.parent);
322	        let is_root = parent_identity.is_none();
323	        let parent_binding = parent_identity.and_then(|parent| self.lookup(parent));
324	        let parent_transaction = parent_binding
325	            .as_ref()
326	            .and_then(|binding| binding.transaction.upgrade());
327	        let _parent_transaction = parent_transaction
328	            .as_ref()
329	            .map(|transaction| transaction.lock().unwrap_or_else(|p| p.into_inner()));
330	        let parent_snapshot = parent_binding.as_ref().and_then(|parent_binding| {
331	            let parent = parent_identity?;
332	            let lifecycle = parent_binding.lifecycle.upgrade()?;
333	            let lifecycle = lifecycle.lock().unwrap_or_else(|p| p.into_inner());
334	            if !lifecycle.contains_process(parent.tgid.as_raw(), parent.generation) {
335	                return None;
336	            }
337	            let image = parent_binding
338	                .image
339	                .lock()
340	                .unwrap_or_else(|p| p.into_inner())
341	                .clone();
342	            let signals = image.signals.upgrade()?;
343	            let signals = signals.lock().unwrap_or_else(|p| p.into_inner());
344	            let action = signals
345	                .dispositions
346	                .get(&libc::SIGCHLD)
347	                .copied()
348	                .unwrap_or_default();
349	            let disposition = if action.is_ignored() {
350	                PublicationDisposition::Ignored
351	            } else if action.handler == libc::SIG_DFL as u64 {
352	                PublicationDisposition::Default
353	            } else {
354	                PublicationDisposition::Caught
355	            };
356	            let waitable = !action.is_ignored() && action.flags & libc::SA_NOCLDWAIT as u64 == 0;
357	            let pending_generation = signals.pending_generation(libc::SIGCHLD);
358	            Some((parent, disposition, waitable, pending_generation))
359	        });
360	
361	        let mut family = self.family.lock().unwrap_or_else(|p| p.into_inner());
362	        if let Some(exit) = family.terminal.get(&process_key(process)).copied() {
363	            return exit;
364	        }
365	        let blocking_descendant = family
366	            .direct_children
367	            .get(&process_key(process))
368	            .and_then(|children| children.keys().next().copied())
369	            .map(process_identity);
370	        let parent_is_terminal = match parent_identity {
371	            Some(parent) => match family.has_terminal_ancestor(process_key(parent)) {
372	                Ok(_) => family.terminal.contains_key(&process_key(parent)),
373	                Err(ProcessFamilyAncestryError::Cycle { ancestor }) => {
374	                    let exit = ProcessFamilyExit::AncestryCycle {
375	                        ancestor: process_identity(ancestor),
376	                    };
377	                    family.terminal.insert(process_key(process), exit);
378	                    return exit;
379	                }
380	                Err(ProcessFamilyAncestryError::MultipleParents {
381	                    child,
382	                    first_parent,
383	                    second_parent,
384	                }) => {
385	                    let exit = ProcessFamilyExit::MultipleParents {
386	                        child: process_identity(child),
387	                        first_parent: process_identity(first_parent),
388	                        second_parent: process_identity(second_parent),
389	                    };
390	                    family.terminal.insert(process_key(process), exit);
391	                    return exit;
392	                }
393	            },
394	            None => false,
395	        };
396	        let exit = if is_root {
397	            ProcessFamilyExit::Root
398	        } else if parent_is_terminal {
399	            // The direct parent's logical transition, rather than a transitive
400	            // ancestor's host teardown, decides whether this child still has a
401	            // live reaper. Both exits serialize through the direct parent's
402	            // transaction: child-first retains normal waitability, while
403	            // parent-first is consuming run teardown. A terminal root alone
404	            // cannot silently auto-reap a grandchild from its still-live parent.
405	            if let Some(parent) = parent_identity {
406	                let parent_key = process_key(parent);
407	                if let Some(children) = family.direct_children.get_mut(&parent_key) {
408	                    children.remove(&process_key(process));
409	                    if children.is_empty() {
410	                        family.direct_children.remove(&parent_key);
411	                    }
412	                }
413	            }
414	            // No process that is itself terminal can subsequently reap an
415	            // already-published zombie or a still-running direct child. Retire
416	            // those exact edges as part of this consuming teardown transition;
417	            // each later child still recognizes the terminal direct parent by
418	            // generation and takes this same branch.
419	            family.direct_children.remove(&process_key(process));
420	            ProcessFamilyExit::RunTeardownChild { status }
421	        } else if let Some(child) = blocking_descendant {
422	            ProcessFamilyExit::DescendantReparentingUnsupported { child }
423	        } else if let Some((parent, disposition, waitable, pending_generation)) = parent_snapshot {
424	            let completion = reverie::ChildExitCompletion {
425	                parent,
426	                child: process,
427	                status,
428	                waitable,
429	                uid: 0,
430	                user_ticks: 0,
431	                system_ticks: 0,
432	            };
433	            let parent_key = process_key(parent);
434	            let child_key = process_key(process);
435	            let relation_exists = family
436	                .direct_children
437	                .get(&parent_key)
438	                .is_some_and(|children| children.contains_key(&child_key));
439	            if !relation_exists {
440	                let exit = ProcessFamilyExit::ParentChildRelationUnavailable { parent };
441	                family.terminal.insert(process_key(process), exit);
442	                return exit;
443	            }
444	            if waitable {
445	                let relation = family
446	                    .direct_children
447	                    .get_mut(&parent_key)
448	                    .and_then(|children| children.get_mut(&child_key))
449	                    .expect("validated KVM direct-child relation remains present");
450	                *relation = DirectChildState::WaitableZombie;
451	            } else {
452	                let children = family
453	                    .direct_children
454	                    .get_mut(&parent_key)
455	                    .expect("validated KVM parent relation remains present");
456	                children.remove(&child_key);
457	                if children.is_empty() {
458	                    family.direct_children.remove(&parent_key);
459	                }
460	            }
461	            ProcessFamilyExit::Child(ChildExitSnapshot {
462	                completion,
463	                disposition,
464	                pending_generation,
465	            })
466	        } else {
467	            ProcessFamilyExit::ParentGenerationUnavailable {
468	                parent: parent_identity.expect("non-root KVM process retains a parent identity"),
469	            }
470	        };
471	        family.terminal.insert(process_key(process), exit);
472	        exit
473	    }
