475	    pub(super) fn process_family_exit(
476	        &self,
477	        process: SignalProcessId,
478	    ) -> Option<ProcessFamilyExit> {
479	        self.family
480	            .lock()
481	            .unwrap_or_else(|p| p.into_inner())
482	            .terminal
483	            .get(&process_key(process))
484	            .copied()
485	    }
