487	    pub(super) fn consume_child_wait(&self, parent: SignalProcessId, child_pid: i32) -> bool {
488	        let mut family = self.family.lock().unwrap_or_else(|p| p.into_inner());
489	        let parent_key = process_key(parent);
490	        let Some(children) = family.direct_children.get_mut(&parent_key) else {
491	            return false;
492	        };
493	        let child = children.iter().find_map(|(key, state)| {
494	            (key.0 == child_pid && *state == DirectChildState::WaitableZombie).then_some(*key)
495	        });
496	        let Some(child) = child else {
497	            return false;
498	        };
499	        children.remove(&child);
500	        if children.is_empty() {
501	            family.direct_children.remove(&parent_key);
502	        }
503	        true
504	    }
