922	fn child_exit_signal_event(
923	    completion: reverie::ChildExitCompletion,
924	) -> Result<SignalEvent, PublicationRejection> {
925	    if completion.user_ticks < 0 || completion.system_ticks < 0 {
926	        return Err(PublicationRejection::InvalidCompletion);
927	    }
928	    let (code, status) = match completion.status {
929	        reverie::ExitStatus::Exited(status) if (0..=i32::from(u8::MAX)).contains(&status) => {
930	            (libc::CLD_EXITED, status)
931	        }
932	        reverie::ExitStatus::Exited(_) => {
933	            return Err(PublicationRejection::InvalidCompletion);
934	        }
935	        reverie::ExitStatus::Signaled(signal, true) => (libc::CLD_DUMPED, signal as libc::c_int),
936	        reverie::ExitStatus::Signaled(signal, false) => (libc::CLD_KILLED, signal as libc::c_int),
937	    };
938	    let mut info = [0; reverie::SIGNAL_INFO_SIZE];
939	    info[..4].copy_from_slice(&libc::SIGCHLD.to_ne_bytes());
940	    info[8..12].copy_from_slice(&code.to_ne_bytes());
941	    info[16..20].copy_from_slice(&completion.child.tgid.as_raw().to_ne_bytes());
942	    info[20..24].copy_from_slice(&completion.uid.to_ne_bytes());
943	    info[24..28].copy_from_slice(&status.to_ne_bytes());
944	    info[32..40].copy_from_slice(&completion.user_ticks.to_ne_bytes());
945	    info[40..48].copy_from_slice(&completion.system_ticks.to_ne_bytes());
946	    let event = SignalEvent::new(
947	        libc::SIGCHLD,
948	        info,
949	        reverie::SignalTarget::Process {
950	            pid: completion.parent.tgid,
951	        },
952	    );
953	    event.map_err(|_| PublicationRejection::InvalidCompletion)
954	}
