1055	fn report_publication_failure(
1056	    registry: &ProcessSignalRegistry,
1057	    process: SignalProcessId,
1058	    phase: &'static str,
1059	    error: crate::Error,
1060	) -> Result<(), Errno> {
1061	    let run = registry
1062	        .run_failure
1063	        .lock()
1064	        .unwrap_or_else(|p| p.into_inner())
1065	        .upgrade()
1066	        .ok_or(Errno::ESRCH)?;
1067	    if registry.failure_forwarded.swap(true, Ordering::AcqRel) {
1068	        return Ok(());
1069	    }
1070	    // No scheduler, registry, image or signal lock survives this call.
1071	    let context = crate::failure::FailureContext::new(run, process.tgid, process.tgid);
1072	    let published = context.publish(phase, error);
1073	    // The first run cause may be a concurrent independent failure. Keep this
1074	    // returned Error too, so root completion retains the committed publication
1075	    // receipt as secondary cleanup rather than losing it.
1076	    registry
1077	        .reported_failure
1078	        .lock()
1079	        .unwrap_or_else(|p| p.into_inner())
1080	        .get_or_insert(published);
1081	    Ok(())
1082	}
