1134	    fn signal_recipients(
1135	        &self,
1136	        process: SignalProcessId,
1137	        signal: i32,
1138	    ) -> Result<Vec<reverie::SignalRecipient>, Errno> {
1139	        if !(1..=64).contains(&signal) {
1140	            return Err(Errno::EINVAL);
1141	        }
1142	        let registry = self.0.upgrade().ok_or(Errno::ESRCH)?;
1143	        let binding = registry.lookup(process).ok_or(Errno::ESRCH)?;
1144	        let image = binding
1145	            .image
1146	            .lock()
1147	            .unwrap_or_else(|p| p.into_inner())
1148	            .clone();
1149	        let transaction = binding.transaction.upgrade().ok_or(Errno::ESRCH)?;
1150	        let lifecycle = binding.lifecycle.upgrade().ok_or(Errno::ESRCH)?;
1151	        let signals = image.signals.upgrade().ok_or(Errno::ESRCH)?;
1152	        let _transaction = transaction.lock().unwrap_or_else(|p| p.into_inner());
1153	        if binding
1154	            .image
1155	            .lock()
1156	            .unwrap_or_else(|p| p.into_inner())
1157	            .revision
1158	            != image.revision
1159	        {
1160	            return Err(Errno::EAGAIN);
1161	        }
1162	        let lifecycle = lifecycle.lock().unwrap_or_else(|p| p.into_inner());
1163	        let signals = signals.lock().unwrap_or_else(|p| p.into_inner());
1164	        let mut signal_mask = crate::signal::KernelSigset::default();
1165	        signal_mask.insert(signal);
1166	        if !signals
1167	            .shared_pending
1168	            .any_matching(signal_mask, &signals.pending_generations)
1169	        {
1170	            return Ok(Vec::new());
1171	        }
1172	        let mut recipients = Vec::new();
1173	        for task in lifecycle.signal_process_tasks(process) {
1174	            let Some(thread) = lifecycle.signal_target(task.tid.as_raw()) else {
1175	                continue;
1176	            };
1177	            if !thread.lock().blocked.contains(signal) {
1178	                recipients.push(reverie::SignalRecipient { task });
1179	            }
1180	        }
1181	        recipients.sort_by_key(|recipient| recipient.task.tid);
1182	        Ok(recipients)
1183	    }
