/// otherwise unchanged.
async fn queue_child_exit_signal(
    &mut self,
    _event: SignalEvent,
) -> crate::ChildExitSignalOutcome {
    crate::ChildExitSignalOutcome::RejectedBeforeCommit {
        kind: crate::ChildExitSignalErrorKind::Unsupported,
        errno: Errno::ENOSYS,
